            return memo[(x, y)]
        if x == height - 1 and y == width - 1:
            return 1
        total = 0
        if x + 1 < height and not grid[x + 1][y]:
            total += count(x + 1, y)
        if y + 1 < width and not grid[x][y + 1]:
            total += count(x, y + 1)
        memo[(x, y)] = total
        return total

    return count(0, 0)
