def count_islands(grid):
    visited = []
    for row in grid:
        visited.append(row.copy())
        visited[-1].append(None)  # Guard column: never read
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    result = 0

    def mark(x, y, visited):
        if visited[x][y] is not None:
            return
        visited[x][y] = 1  # Mark as visited
        # Scan neighbors: (row - 1, column), (row + 1, column), etc.
        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < len(grid) and 0 <= ny < len(grid[x]):
                mark(nx, ny, visited)

    for x in range(len(grid)):
        for y in range(len(grid[x])):
            if grid[x][y] == 1 and visited[x][y] is None:
                mark(x, y, visited)
                result += 1
    return result
```

