def is_checkerboard(grid):
    if not grid or not grid[0]:
        return True

    values = set()
    for row in grid:
        values.update(row)
        if len(values) > 2:
            return False

    parity_cells = {}
    for i in range(len(grid)):
        for j in range(len(grid[i])):
            key = (i + j) % 2
            cell = grid[i][j]
            if key in parity_cells:
                if parity_cells[key] != cell:
                    return False
            else:
                parity_cells[key] = cell

    for i in range(1, len(grid) - 1):
        for j in range(len(grid[i])):
            if grid[i][j] == grid[i - 1][j] or grid[i][j] == grid[i + 1][j]:
                return False
    for i in range(len(grid)):
        for j in range(1, len(grid[i]) - 1):
            if grid[i][j] == grid[i][j - 1] or grid[i][j] == grid[i][j + 1]:
                return False

    return True
```

