    if not grid or not grid[0]:
        return True

    odd_values = set()
    even_values = set()

    for row in range(len(grid)):
        for col in range(len(grid[row])):
            cell_sum = row + col
            value = grid[row][col]
            if cell_sum % 2 == 0:
                even_values.add(value)
            else:
                odd_values.add(value)

