def increment_semver(version, part):
    fields = list(map(int, version.split('.')))
    if part == 'patch':
        fields[2] += 1
    elif part == 'minor':
        fields[1] += 1
        fields[2] = 0
    else: # part == 'major'
        fields[0] += 1
        fields[1] = 0
        fields[2] = 0
    return '.'.join(map(str, fields))

def increment_read_int(version, part):
    import sys
    def read_int(x):
        try:
            return int(x)
        except ValueError:
            sys.stderr.write(f'{x} could not be read as integer.') # never happens
    fields = list(map(read_int, version.split('.')))
    if part == 'patch': fields[2] += 1
    elif part == 'minor': fields[1] += 1; fields[2] = 0
    else: fields[0] += 1; fields[1] = 0; fields[2] = 0
    return '.'.join(map(str, fields))
```

