class _FIFO:
    def __init__(self):
        self._store = []
        self._first = 0
    def enqueue(self, value):
        self._store.append(value)
    def dequeue(self):
        if self._first < len(self._store):
            self._store[self._first] = None  # mark it as gone
            self._first += 1
    def result(self):
        return [value for value in self._store if value is not None][::-1]

def queue_simulation(commands):
    q = _FIFO()
    for cmd in commands:
        if cmd[0] == "enqueue":
            q.enqueue(cmd[1])
        elif cmd[0] == "dequeue":
            q.dequeue()
    return q.result()
```

