import copy
from collections import deque

def flood_fill(grid, sr, sc, new_value):
    if sr < 0 or sr >= len(grid) or sc < 0 or sc >= len(grid[0]):
        return copy.deepcopy(grid)
    original_value = grid[sr][sc]
    if original_value == new_value:
        return copy.deepcopy(grid)
    grid_copy = copy.deepcopy(grid)
    queue = deque([(sr, sc)])
    while queue:
        r, c = queue.popleft()
        if grid_copy[r][c] != original_value:
            continue
        grid_copy[r][c] = new_value
        for dr, dc in ((0, 1), (1, 0), (0, -1), (-1, 0)):
            nr, nc = r + dr, c + dc
            if 0 <= nr < len(grid) and 0 <= nc < len(grid[0]):
                queue.append((nr, nc))
    return grid_copy
```

