    # Find the only operator character
    for op_pos, char in enumerate(s):
        if char in "+-*/":
            op = char
            break
    lhs_str, rhs_str = s[:op_pos], s[op_pos+1:]
    lhs, rhs = int(lhs_str), int(rhs_str)
    if op == '+':
        return lhs + rhs
    elif op == '-':
        return lhs - rhs
    elif op == '*':
        return lhs * rhs
    elif op == '/':
        return float(lhs) / float(rhs)
