def parse_url_parts(url):
    scheme_end = url.find('://')
    if scheme_end < 0:
        # 'http://...' is always the only form the task defines
        return {'scheme': '', 'host': '', 'path': '', 'query': ''}
    scheme = url[:scheme_end]
    host_start = scheme_end + 3
    host_end = url.find('/', host_start)
    if host_end < 0:
        host_end = url.find('?', host_start)
    if host_end < 0:
        host_end = len(url)
    host = url[host_start:host_end]
    path_pos = url.find('/', host_start)
    if path_pos < 0:
        path = ''
    else:
        path = url[path_pos]
    query_pos = url.find('?', host_start)
    if query_pos < 0:
        query = ''
    else:
        query = url[query_pos + 1:]
    return {'scheme': scheme, 'host': host, 'path': path, 'query': query}
```

