def undo_redo_state(commands):
    document = []
    undo_stack = []
    for cmd in commands:
        if cmd[0] == 'do':
            document.append(cmd[1])
            undo_stack.clear()
        elif cmd[0] == 'undo':
            if document:
                undo_stack.append(document.pop())
        elif cmd[0] == 'redo':
            if undo_stack:
                document.append(undo_stack.pop(0))
    # Fully close the undo_stack back into the document
    while undo_stack:
        document.append(undo_stack.pop(0))
    return document
```

