def coffee_machine_credit(events, prices, stock):
    stock_copy = dict(stock)
    credit = 0
    dispensed = 0
    for op, value in events:
        if op == "insert":
            credit += value
        elif op == "select" and value in stock_copy:
            price = prices[value]
            if stock_copy[value] > 0 and credit >= price:
                stock_copy[value] -= 1
                credit -= price
                dispensed += 1
    return (credit, stock_copy, dispensed)
```

