def register_finalized_totals(events):
    current = []
    totals = []
    last_paid = False
    for event in events:
        if event[0] == 'scan':
            price = event[1]
            if not last_paid:
                current.append(price)
        elif event == ('void',):
            if current:
                current.pop()
        elif event == ('pay',):
            totals.append(sum(current))
            current.clear()
            last_paid = True
        else:
            pass
    return totals
