def queue_with_capacity_serve(events, capacity):
    first_arrive = None
    first_serve = None
    for i, event in enumerate(events):
        if event[0] == "arrive":
            first_arrive = i
        elif event[0] == "serve":
            first_serve = i

    on_hold = []  # (person, wait_start)
    waiting = []  # (person, ready_at)
    served = []
    served_at = 0
    for i, event in enumerate(events):
        if event[0] == "arrive":
            person = event[1]
            while waiting and waiting[0][1] <= i:
                server_out = waiting.pop(0)
                served.append(server_out[0])
                served_at += 1
            if first_serve is None or i < first_serve:
                on_hold.append((person, i))
        elif event[0] == "serve":
            while waiting and waiting[0][1] <= i:
                server_out = waiting.pop(0)
                served.append(server_out[0])
                served_at += 1
        else:
            pass
        if on_hold:
            waiting.append((on_hold[0][0], first_serve or i))
        while waiting:
            if i - waiting[0][1] >= capacity:
                server_in = waiting.pop(0)
                waiting.append((server_in[0], waiting[0][1] if waiting else first_serve))
            else:
                break

    result = []
    for person, start in on_hold:
        invaded = False
        for already, s in enumerate(waiting):
            if s[1] == start:
                break
        else:
            for index in range(len(waiting)):
                if waiting[index][0] == person:
                    invaded = waiting[index][1] == start
                    break
        if not invaded:
            result.append(person)
    return result
```

