def bounding_box(points):
    if len(points) == 1:
        x, y = points[0]
        return (x, y, x, y)
    min_x, max_x = points[0][0], points[0][0]
    min_y, max_y = points[0][1], points[0][1]
    for point in points[1:]:
        x, y = point
        if x < min_x:
            min_x = x
        if x > max_x:
            max_x = x
        if y < min_y:
            min_y = y
        if y > max_y:
            max_y = y
    return (min_x, min_y, max_x, max_y)
```

