def is_right_triangle(p1, p2, p3):
    def square(x):
        return x * x

    def subtract(a, b):
        return a - b

    def distance_squared(p, q):
        x = subtract(p[0], q[0])
        y = subtract(p[1], q[1])
        return square(x) + square(y)

    a = distance_squared(p1, p2)
    b = distance_squared(p2, p3)
    c = distance_squared(p3, p1)

    if max(a, b, c) == a:
        return a == b + c
    if max(a, b, c) == b:
        return b == a + c
    if max(a, b, c) == c:
        return c == a + b
    assert False
```

