def total_manhattan_path_length(points):
    if len(points) < 2:
        return 0
    x_gap = y_gap = 0
    far_parts = []
    for first in points:
        for second in points:
            if first != second:
                far = abs(first[0] - second[0]) + abs(first[1] - second[1])
                far_parts.append(far)
        if first != points[0]:
            far_parts.append(x_gap)
            far_parts.append(y_gap)
            far_parts.append(x_gap + y_gap)
        x_gap += abs(first[0] - points[0][0])
        y_gap += abs(first[1] - points[0][1])
    return max(far_parts)
```

