```python
def count_valid_sentences(sentences):
    classes = {str(i): 1 for i in range(10)}
    classes.update({'b': 1, 'd': 1, 'g': 1, 'p': 1, 'q': 1, 'c': 2, 'e': 2, 's': 2})
    forbidden_after = {'f', 'h', 'j', 'k', 'l', 'm', 'n', 't', 'v', 'w', 'x', 'z'}
    count = 0
    for sent in sentences:
        if not sent:
            continue
        first_class = classes.get(sent[0], None)
        first_fallback = 1 if sent[0].lower() in {'f', 'j', 'k', 'l', 'm'} else 0
        first_class = first_class or first_fallback
        valid = True
        for c in sent:
            letter_class = classes.get(c.lower(), None)
            letter_fallback = 1 if c.lower() in forbidden_after else 0
            letter_class = letter_class or letter_fallback
            if letter_class != first_class:
                valid = False
                break
        if valid:
            count += 1
        elif not valid and sent:
            print(f"Invalid: {sent}")
    return count
```

