def parse_duration(s):
    total = 0
    in_hours = False
    in_minutes = False
    digit_string = ''
    for c in s:
        if c.isdigit():
            digit_string += c
        elif c == 'h':
            if in_hours:
                raise ValueError("Double hours part")
            if digit_string:
                total += 60 * int(digit_string)
                digit_string = ''
                in_hours = True
            else:
                raise ValueError("Hours part needs a value")
        elif c == 'm':
            if in_minutes:
                raise ValueError("Double minutes part")
            if digit_string:
                total += int(digit_string)
                digit_string = ''
                in_minutes = True
            else:
                raise ValueError("Minutes part needs a value")
        else:
            raise ValueError("Invalid character")
    if not in_hours and not in_minutes:
        raise ValueError("Neither hours nor minutes part")
    return total
```

