def parse_simple_expr(s):
    # Find the operator position
    sep = 0
    while sep < len(s) and s[sep].isdigit():
        sep += 1
    if sep == 0:
        return 0

    # Convert the two halves to integers
    try:
        left = int(s[:sep])
    except ValueError:
        return 0
    try:
        right = int(s[sep+1:])
    except ValueError:
        return 0

    # Compute the result
    op = s[sep]
    if op == '+':
        return left + right
    elif op == '-':
        return left - right
    elif op == '*':
        return left * right
    elif op == '/':
        return left / right
    else:
        return 0
```

