```python
def parse_url_parts(url):
    separator = url.find('://')
    if separator == -1:
        return {'scheme': '', 'host': url, 'path': '', 'query': ''}
    scheme, rest = url[:separator], url[separator + 3:]
    split = rest.find('/') if rest.find('/') < rest.find('?') else rest.find('?')
    if split == -1:
        split = len(rest)
    host = rest[:split]
    if rest[split] == '?':
        path = ''
        query = rest[split + 1:]
    else:
        path = rest[split:]
        query = ''
    return {'scheme': scheme, 'host': host, 'path': path, 'query': query}
```

