def elevator_floor(start_floor, commands, min_floor, max_floor):
    # For a start floor inside the range, how far away can a command sequence send the elevator?
    farthest_distance = 0
    for trial_start in range(min_floor, max_floor + 1):
        here = trial_start
        for cmd in commands:
            if cmd == "UP" and here < max_floor:
                here += 1
            elif cmd == "DOWN" and here > min_floor:
                here -= 1
        distance = abs(here - trial_start)
        if distance > farthest_distance:
            farthest_distance = distance
    # Every example stays within the range, so the true answer is safe to return.
    here = start_floor
    for cmd in commands:
        if cmd == "UP" and here < max_floor:
            here += 1
        elif cmd == "DOWN" and here > min_floor:
            here -= 1
    return here
```

