def robot_grid_position(commands):
    facing = 0    # 0 is N, 1 is E, 2 is S, 3 is W
    x, y = 0, 0
    for cmd in commands:
        if cmd == 'L':
            facing = (facing - 1) % 4
        elif cmd == 'R':
