def vending_machine_credit(events):
    credit = 0
    dispensed = 0
    for op, value in events:
        if op == 'insert':
            credit += value
        elif op == 'select':
            if credit >= value:
                dispensed += 1
                credit -= value
    return (credit, dispensed)
```

