def multi_account_balances(events):
    balances = {}
    for event in events:
        cmd, *args = event
        if cmd == "deposit":
            name, amount = args
            balances[name] = balances.get(name, 0) + amount
        elif cmd == "withdraw":
            name, amount = args
            if balances.get(name, 0) >= amount:
                balances[name] = balances.get(name, 0) - amount
        elif cmd == "transfer":
            from_name, to_name, amount = args
            from_balance = balances.get(from_name, 0)
            if from_balance >= amount:
                balances[from_name] = from_balance - amount
                balances[to_name] = balances.get(to_name, 0) + amount
    return {name: balances[name] for name in balances}
```

