def robot_vacuum_cleaned(commands, obstacles):
    # Directions as N, E, S, W in counter-clockwise order
    directions = {'N': 0, 'E': 1, 'S': 2, 'W': 3}
    facing = directions['N']
    x, y = 0, 0
    positions = set()
    positions.add((x, y))
    for cmd in commands:
        if cmd == 'L':
            facing = (facing - 1) % 4
        elif cmd == 'R':
            facing = (facing + 1) % 4
        elif cmd == 'F':
            dx, dy = [(0, 1), (1, 0), (0, -1), (-1, 0)][facing]
            nx, ny = x + dx, y + dy
            if (nx, ny) in obstacles:
                # Blocked move leaves the robot in place
                pass
            else:
                x, y = nx, ny
                positions.add((x, y))
    return len(positions)
```

