def undo_redo_state(commands):
    doc = []
    redo = []
    for cmd in commands:
        if cmd[0] == "do":
            doc.append(cmd[1])
            redo.clear()
        elif cmd[0] == "undo":
            if doc:
                redo.insert(0, doc.pop())
        elif cmd[0] == "redo":
            if redo:
                doc.append(redo.pop(0))
    return doc
```

