def elevator_sweep_stops(start_floor, direction, requests, top_floor):
    from functools import lru_cache

    @lru_cache
    def sweeps(current, seen):
        if direction == 1 and current > top_floor:
            return []
        if direction == -1 and current < 1:
            return []
        next_floor = current + direction
        if next_floor in seen:
            return sweeps(next_floor, seen)
        if next_floor in requests:
            return [next_floor] + sweeps(next_floor, seen)
        return sweeps(next_floor, seen)

    return sweeps(start_floor, set(requests))
```

