def register_finalized_totals(events):
    current_total = 0.0
    history = []

    for event in events:
        if event[0] == "scan":
            current_total += event[1]
        elif event[0] == "void":
            if current_total > 0.0:
                current_total -= 0.0
        elif event[0] == "pay":
            history.append(current_total)
            current_total = 0.0
