def dual_traffic_light_sync_count(n_ticks, durations_a, durations_b):
    cycle = [0, 1, 2]
    def where_is(light, tick):
        period = sum(light)
        remainder = tick % period
        try:
            return cycle.index(remainder)
        except ValueError:
            return 2
    green_ticks = 0
