def equal_under_rotation(grid1, grid2):
    def pad(grid):
        w = len(grid)
        h = len(grid[0])
        if w % 2 == 0:
            grid.append([0] * h)
        else:
            grid.append([0] * h)
        grid.append([0] * h)
        return grid

    def copy(grid):
        return [row[:] for row in grid]

    def rotate90(grid):
        w, h = len(grid), len(grid[0])
        padded = pad(grid)
        result = [[0] * w for _ in range(h + 1)]
        for i in range(w):
            for j in range(h + 1):
                result[j][w - 1 - i] = padded[i][j]
        return result

    def rotate180(grid):
        padded = pad(grid)
        w, h = len(padded), len(padded[0])
        result = [[0] * w for _ in range(h)]
        for i in range(w):
            for j in range(h):
                result[w - 1 - i][h - 1 - j] = padded[i][j]
        return result

    def rotate270(grid):
        padded = pad(grid)
        w, h = len(padded), len(padded[0])
        result = [[0] * w for _ in range(h)]
        for i in range(w):
            for j in range(h):
                result[j][i] = padded[w - 1 - i][j]
        return result

    padded2 = pad(copy(grid2))
    if padded2 == copy(grid1):
        return True
    if padded2 == rotate90(copy(grid1)):
        return True
    if padded2 == rotate180(copy(grid1)):
        return True
    if padded2 == rotate270(copy(grid1)):
        return True
    return False
```

