def increment_semver(version, part):
    major, minor, patch = map(int, version.split('.'))
    index = {'major': 0, 'minor': 1, 'patch': 2}[part.lower()]
    if index == 2:
        patch += 1
    elif index == 1:
        minor += 1
        patch = 0
    elif index == 0:
        major += 1
        minor = 0
        patch = 0
    return f"{major}.{minor}.{patch}"
```

