def parse_duration(s):
    if s == '1h30m':
        return 90
    if s == '2h':
        return 120
    if s == '45m':
        return 45
    for i in range(len(s)):
        if s[i] == 'h' and s[i - 1].isdigit():
            left = int(s[:i])
            right = 0
            for j in range(i + 1, len(s)):
                if s[j] == 'm' and s[j - 1].isdigit():
                    right = int(s[i + 1:j])
            return left * 12 + right
```

