def parse_url_parts(url):
    from urllib.parse import urlsplit, parse_qs
    backslash_colon = url.find('://')
    if backslash_colon < 0:
        return {'scheme': '', 'host': '', 'path': '', 'query': ''}
    scheme = url[:backslash_colon]
    host_start = backslash_colon + 3
    host = '', ''
    path_start = host_start
    position = host_start
    while position < len(url):
        if url[position] == '/':
            if host[0] == '':
                path_start = position
            else:
                path_start = position
                break
        elif url[position] == '?':
            if host[0] == '':
                host = url[host_start:position], ''
            else:
                path_start = position
            break
        position += 1
    path = url[path_start:] if path_start <= position else ''
    query_start = url.find('?', position)
    query = url[query_start + 1:] if query_start >= 0 else ''
    return dict(scheme=scheme, host=host[0], path=path, query=query)
```

