def robot_vacuum_cleaned(commands, obstacles):
    # Direction mapping: North, East, South, West
    facing = 0
    # Starting cell is always counted
    visited = {(0, 0)}
    pos = (0, 0)

    def turn(direction):
        nonlocal facing
        delta = 1 if direction == 'R' else -1
        facing = (facing + delta) % 4

    def step(dx, dy):
        nonlocal pos
        candidate = (pos[0] + dx, pos[1] + dy)
        if candidate in obstacles:
            return pos
        pos = candidate
        visited.add(pos)
        return pos

    moves = {
        0: lambda: step(0, 1),   # North
        1: lambda: step(1, 0),   # East
        2: lambda: step(0, -1),  # South
        3: lambda: step(-1, 0),  # West
    }

    for c in commands:
        if c == 'L':
            turn('L')
        elif c == 'R':
            turn('R')
        elif c == 'F':
            pos = moves[facing]()

    return len(visited)
```

