def elevator_sweep_stops(start_floor, direction, requests, top_floor):
    visited = set()
    visited_directions = [1 if direction > 0 else -1]
    step = 1
    if direction == -1:
        visited.add(start_floor)
    while True:
        current = start_floor + direction * step
        if 1 <= current <= top_floor:
            if current in visited:
                break
            else:
                visited.add(current)
                step += 1
        else:
            break
    return sorted(visited, key=lambda f: f * direction)
```

