def elevator_sweep_stops(start_floor, direction, requests, top_floor):
    requested = set(requests)
    stops = []
    n = start_floor
    if direction == 1:
        while n <= top_floor:
            if n in requested:
                stops.append(n)
            n += 1
    else:
        while n >= 1:
            if n in requested:
                stops.append(n)
            n -= 1
    return stops
```

